import csv
import io
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"', strict=False)

    records: List[List[str]] = []
    for record in reader:
        if not record or all(value.strip() == "" for value in record):
            continue
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 7
    header_index = None

    for index, record in enumerate(records):
        normalized = [value.strip().upper() for value in record]
        if (
            len(record) == expected_width
            and len(normalized) >= 2
            and normalized[0] == "ENTITY"
            and normalized[1] == "DATE"
        ):
            header_index = index
            break

    if header_index is None:
        header_index = 0

    columns = records[header_index]
    data_records = records[header_index + 1:]

    width = len(columns) or expected_width
    normalized_rows: List[List[str]] = []

    for record in data_records:
        if len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        elif len(record) < width:
            record = record + [""] * (width - len(record))
        normalized_rows.append(record)

    return {"columns": columns, "rows": normalized_rows}
